const profiles = [
  { key: 'quality', label: 'Maximum Quality', result: 'Resultado — Maximum Quality', metric: 'Economia — Maximum Quality' },
  { key: 'balanced', label: 'Balanced', result: 'Resultado — Balanced', metric: 'Economia — Balanced' },
  { key: 'maximum', label: 'Maximum Savings', result: 'Resultado — Maximum Savings', metric: 'Economia — Maximum Savings' }
];
const baseline = String($('Resultado — Baseline').first().json.baseline_output || '');
const expected = ["LEAD-1942","Campinas/SP","R$ 850.000,00","05/08/2026 14:30","false"];
const normalize = (value) => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const rows = profiles.map((profile) => {
  const output = String($(profile.result).first().json[profile.key + '_output'] || '');
  const savings = $(profile.metric).first().json.tokenSavings || {};
  const factsPreserved = expected.every((fact) => normalize(output).includes(normalize(fact)));
  return { profile: profile.label, ...savings, factsPreserved, outputMatchesBaseline: output === baseline };
});
const report = ['## Comparação real — 60 registros'];
for (const row of rows) report.push('**' + row.profile + ':** ' + row.before + ' → ' + row.after + ' tokens; economia ' + row.percent + '%; fatos 5/5: ' + (row.factsPreserved ? 'sim' : 'não'));
return [{ json: {
  output: report.join('\n'),
  datasetRecords: 60,
  model: 'models/gemini-2.5-flash',
  measurement: 'provider',
  baselineOutput: baseline,
  profiles: rows,
  allFactsPreserved: rows.every((row) => row.factsPreserved),
  allOutputsMatchBaseline: rows.every((row) => row.outputMatchesBaseline)
} }];
